<?php
namespace Tivoli\Service;
use RuntimeException;
use Throwable;
use Tivoli\Security\PermissionDenied;

trait ReminderDelivery
{
    public function services():array{return (new \Tivoli\Infrastructure\ReminderTransport($this->config))->readiness();}
    private function contact(array $prefs,string $channel):string{return $channel==='email'?$prefs['email_address']:$prefs['phone'];}
    public function deliveries(int $actor):array{
        $this->permit($actor);$out=[];foreach($this->journal->events('n_delivery') as $e){if((int)$e['data']['recipient']!==$actor)continue;$states=$this->journal->events('n_delivery_state',(string)$e['id']);$last=$states?end($states):null;$data=$e['data'];$data['state']=$last['data']['state']??'queued';$data['attempts']=0;$data['provider_id']='';$data['next_at']='';$data['last_state_at']=$last['created_at']??$e['created_at'];foreach($states as $state){if($state['kind']==='nt_send_intent')$data['attempts']++;if(isset($state['data']['members']))$data['members']=$state['data']['members'];if(isset($state['data']['provider_id']))$data['provider_id']=$state['data']['provider_id'];if(isset($state['data']['next_at']))$data['next_at']=$state['data']['next_at'];} $out[]=$e+['position'=>$data];}return $out;
    }
    private function cancelUnsent(int $recipient):void{
        $p=$this->prefs($recipient);foreach($this->deliveries($recipient) as $d){$v=$d['position'];if(in_array($v['state'],['accepted','delivered','unknown','sending','cancelled'],true))continue;$ch=$v['channel'];if(!$p[$ch]||($ch==='whatsapp'&&!$p['consent'])||!hash_equals($v['contact'],$this->contactFingerprint($recipient,$ch,$this->contact($p,$ch))))$this->journal->event($recipient,'nt_delivery_cancelled','n_delivery_state',(string)$d['id'],['state'=>'cancelled','reason'=>'preference_or_contact_changed']);}
    }
    private function queueDeliveries(int $actor,array $members,bool $daily):void{
        $ready=$this->services();$today=substr($this->now(),0,10);
        foreach($members as $recipient=>$entries){$p=$this->prefs((int)$recipient);foreach(['email','whatsapp'] as $ch){if(!$p[$ch]||($ch==='whatsapp'&&!$p['consent']))continue;$fingerprint=$this->contactFingerprint((int)$recipient,$ch,$this->contact($p,$ch));$groups=[];if($daily)$groups['daily']=array_values(array_filter($entries,fn($m)=>!$m['critical']));foreach($entries as $m)if($m['critical'])$groups['urgent:'.$m['source'].':'.$m['episode']]=[$m];
                foreach($groups as $group=>$tasks){if(!$tasks)continue;$state=!$ready[$ch]?'setup':(!$p[$ch.'_verified']?'verification':'queued');$claim=$this->journal->unique('n_delivery',[$recipient,$ch,$today,$group,$fingerprint],function($hash)use($actor,$recipient,$ch,$today,$group,$fingerprint,$tasks,$state){$id=$this->journal->event($actor,'nt_delivery','n_delivery',$hash,['recipient'=>(int)$recipient,'channel'=>$ch,'slot'=>$today,'group'=>$group,'contact'=>$fingerprint,'members'=>$tasks]);$this->journal->event($actor,'nt_delivery_queued','n_delivery_state',(string)$id,['state'=>$state]);return $id;});
                    if(!$claim['created'])foreach($this->deliveries((int)$recipient) as $old)if($old['id']===$claim['id']){$v=$old['position'];if(!in_array($v['state'],['accepted','delivered','unknown','sending'],true)&&($v['members']!==$tasks||$v['state']==='cancelled'))$this->journal->event($actor,'nt_delivery_members','n_delivery_state',(string)$claim['id'],['state'=>$v['state']==='failed'?'failed':$state,'members'=>$tasks]);break;}
                }
            }}
    }
    /** A durable intent precedes network I/O. Abandoned intents are never blindly resent. */
    public function dispatch(int $actor,?callable $send=null):array{
        $this->requireOwner($actor);if($send!==null&&getenv('TIVOLI_TEST_MODE')!=='1')throw new RuntimeException('Injected notification transports are test-only.');$sent=0;$held=0;
        $ids=$this->access->repo->run("SELECT id FROM finance_events WHERE target_type='n_delivery' AND kind='nt_delivery' ORDER BY id")->fetchAll(\PDO::FETCH_COLUMN);
        foreach($ids as $id){if($sent>=10)break;$job=$this->access->transaction(function()use($actor,$id){
                $this->requireOwner($actor);$this->sources->reset();$root=$this->journal->find((int)$id);$recipient=(int)$root['data']['recipient'];if(!array_filter($root['data']['members'],fn($m)=>$this->sources->accepts($m['source'])))return null;if(!$this->sources->active($recipient)){$this->deliveryStatus($actor,(int)$id,'cancelled','recipient_unavailable');return null;}
                $position=null;foreach($this->deliveries($recipient) as $d)if($d['id']===(int)$id){$position=$d['position'];break;}if($position&&$position['state']==='sending'&&$position['last_state_at']<(new \DateTimeImmutable($this->now(),new \DateTimeZone('UTC')))->modify('-5 minutes')->format('Y-m-d H:i:s')){$this->deliveryStatus($actor,(int)$id,'unknown','abandoned_send_intent');return null;}if(!$position||in_array($position['state'],['accepted','delivered','unknown','sending','cancelled'],true))return null;if($position['slot']<substr($this->now(),0,10)){$this->deliveryStatus($actor,(int)$id,'cancelled','obsolete_unsent_slot');return null;}if($position['attempts']>=3||($position['next_at']!==''&&$position['next_at']>$this->now()))return null;
                $p=$this->prefs($recipient);$ch=$position['channel'];if(!$p[$ch]||($ch==='whatsapp'&&!$p['consent'])||!hash_equals($position['contact'],$this->contactFingerprint($recipient,$ch,$this->contact($p,$ch)))){$this->deliveryStatus($actor,(int)$id,'cancelled','preferences_or_contact_changed');return null;}
                if(!$this->services()[$ch]){$this->deliveryStatus($actor,(int)$id,'setup','service_not_ready');return null;}if(!$p[$ch.'_verified']){$this->deliveryStatus($actor,(int)$id,'verification','contact_not_verified');return null;}
                $members=[];$unknown=false;foreach($position['members'] as $m){try{$row=$this->sources->inspect($recipient,$m['source'],true);if($row['unavailable']){$unknown=true;continue;}if($row['resolved']||!($row['actionable']??true)||!$this->sources->shouldReceive($row,$recipient))continue;if($recipient===$this->sources->owner()&&$this->sources->episode($row)!==$m['episode'])continue;$members[]=$m;}catch(PermissionDenied){continue;}catch(Throwable){$unknown=true;}}
                if(!$members){$this->deliveryStatus($actor,(int)$id,$unknown?'source_unavailable':'cancelled',$unknown?'source_unavailable':'no_current_authorized_work');return null;}
                $attempt=bin2hex(random_bytes(16));$this->journal->event($actor,'nt_send_intent','n_delivery_state',(string)$id,['state'=>'sending','attempt'=>$attempt,'eligible_members'=>$members]);$this->access->audit($actor,'reminders.send_intent','notification_delivery',(string)$id,'succeeded',['channel'=>$ch]);return ['id'=>(int)$id,'channel'=>$ch,'recipient'=>$recipient,'destination'=>$this->contact($p,$ch),'attempt'=>$attempt];
            });if(!$job){$held++;continue;}
            try{$result=$send?$send($job):(new \Tivoli\Infrastructure\ReminderTransport($this->config))->send($job);if(!is_array($result)||!in_array($result['state']??'', ['accepted','failed','unknown'],true))$result=['state'=>'unknown'];}catch(Throwable){$result=['state'=>'unknown'];}
            $this->access->transaction(function()use($actor,$job,$result){$this->requireOwner($actor);$last=$this->journal->latest('n_delivery_state',(string)$job['id']);if($last['data']['state']==='delivered'){$this->journal->event($actor,'nt_delivery_reply','n_delivery_receipt',(string)$job['id'],['state'=>$result['state'],'attempt'=>$job['attempt'],'provider_id'=>(string)($result['provider_id']??'')]);$this->access->audit($actor,'reminders.delivery_reply','notification_delivery',(string)$job['id'],'recorded');return;}if(($last['data']['attempt']??'')===$job['attempt']&&in_array($last['data']['state'],['accepted','delivered','failed'],true))return;if(($last['data']['attempt']??'')!==$job['attempt']||$last['data']['state']!=='sending')throw new RuntimeException('Delivery outcome requires review.');$state=$result['state'];$data=['state'=>$state,'attempt'=>$job['attempt']];if($state==='accepted')$data['provider_id']=(string)($result['provider_id']??'');if($state==='failed')$data['next_at']=(new \DateTimeImmutable($this->now(),new \DateTimeZone('UTC')))->modify('+10 minutes')->format('Y-m-d H:i:s');$this->journal->event($actor,'nt_delivery_outcome','n_delivery_state',(string)$job['id'],$data);$this->access->audit($actor,'reminders.delivery_outcome','notification_delivery',(string)$job['id'],'recorded',['state'=>$state]);});$sent++;
        }return ['attempted'=>$sent,'held'=>$held];
    }
    private function deliveryStatus(int $actor,int $id,string $state,string $reason):void{
        $last=$this->journal->latest('n_delivery_state',(string)$id);if(($last['data']['state']??'')===$state)return;$this->journal->event($actor,'nt_delivery_status','n_delivery_state',(string)$id,['state'=>$state,'reason'=>$reason]);$this->access->audit($actor,'reminders.delivery_status','notification_delivery',(string)$id,'recorded',['state'=>$state]);
    }
}
